  "Amatörde adın duyuldu. İki bölgesel organizasyon seni profesyonel kadrosuna istiyor!": "О вас заговорили на любительской сцене. Две региональные лиги хотят видеть вас в профессиональном ростере!",
  "🎟️ Dean Wyatt ayağa kalktı: \"{0}, UCC’ye hoş geldin!\"": "🎟️ Дин Уайетт встал: «{0}, добро пожаловать в UCC!»",
  "Kazandın ama Dean etkilenmedi: \"Biraz daha gelişsin.\" Diğer kapılar açık.": "Вы победили, но Дина это не впечатлило: «Пусть ещё подрастёт». Другие двери открыты.",
  "DWCS kötü geçti. UCC kapısı şimdilik kapandı.": "DWCS прошёл неудачно. Двери UCC пока закрыты.",
