  "📋 {0} {1}, {2} dövüşçüsünü yenerek sıralamaya girdi.": "📋 {0} {1} вошёл в рейтинг, победив {2}.",
  "🏆 {0}’da yeni şampiyon: {1} “{2}” {3}!": "🏆 Новый чемпион в весе {0}: {1} «{2}» {3}!",
  "🏆 {0} şampiyonu {1}, kemerini {2} karşısında korudu.": "🏆 Чемпион в весе {0} {1} защитил пояс против {2}.",
  "🌟 Yükselen yıldız: yenilmez {0} “{1}” {2} ({3}-0) sıralamaya #{4}’den girdi!": "🌟 Восходящая звезда: непобеждённый {0} «{1}» {2} ({3}-0) вошёл в рейтинг под №{4}!",
  "👋 {0} {1} ({2}-{3}) eldivenlerini astı.": "👋 {0} {1} ({2}-{3}) повесил перчатки на гвоздь.",
