  "Bu raunt bizim, net! Aynen devam.": "Этот раунд наш, однозначно! Так держать.",
  "Harika gidiyorsun, bozma sakın!": "Ты отлично работаешь, ничего не меняй!",
  "Onu kırdın, gözlerinden okunuyor!": "Ты его сломал, по глазам видно!",
  "Temiz raunt. Nefesini topla, aynısı.": "Чистый раунд. Отдышись, повтори.",
  "Raundu aldık gibi ama yakındı. Hakemlere bırakma.": "Думаю, раунд наш, но было близко. Не оставляй это судьям.",
  "Önündeyiz ama fark az, uyuma!": "Мы впереди, но близко, не спи!",
  "İyi ama yeterli değil. Biraz daha bastır.": "Хорошо, но мало. Поднажми.",
  "Kartlarda öndeyiz sanırım. Riske girme ama geri de durma.": "Думаю, по запискам мы впереди. Не рискуй, но и не отсиживайся.",
  "Başa baş gidiyor. Bir şeyi değiştirmemiz lazım.": "Идём ноздря в ноздрю. Надо что-то менять.",
  "Çok yakın bir raunttu, kimin aldığı belli değil.": "Очень близкий раунд, сложно сказать, чей.",
  "Ortada kaldık. Bu raunt farkı açmalısın.": "Застряли посередине. В этом раунде нужно оторваться.",
  "Denk gidiyor, fark yaratacak olan sensin.": "Равенство, разницу должен сделать ты.",
  "Bu raundu kaybettik, dinle beni! Planı değiştiriyoruz.": "Этот раунд проигран, слушай меня! Меняем план.",
  "Uyan! Bu gidişle kartlar onun!": "Проснись! Так записки будут его!",
  "Kötü raunt. Unut onu, sıfırdan başla.": "Плохой раунд. Забудь, начни заново.",
  "Onun oyununu oynuyoruz. Hemen değiştir!": "Мы играем в его игру. Меняй сейчас же!",
