  "Karakterini Nasıl Kurarsın?": "Как создать персонажа?",
  "🌍 Uyruk: Antrenman imkânı başlangıç istatistiklerini, taraftar desteği başlangıç popülerliğini belirler. İlk salonun ve hocan da ülkene göre gelir.": "🌍 Национальность: возможности тренировок задают стартовые характеристики, поддержка фанатов — стартовую популярность. От страны зависят и первый зал с тренером.",
  "🎂 Yaş (18-30): Genç başlarsan ham ama hızlı gelişirsin (×1.3). Yaşlı başlarsan güçlü başlarsın ama 32’den sonra hız ve çene düşmeye başlar. 41’de emeklilik kaçınılmazdır.": "🎂 Возраст (18-30): начав молодым, вы сырые, но растёте быстро (×1,3). Начав старше, вы сильнее, но после 32 скорость и подбородок начинают падать. В 41 завершение карьеры неизбежно.",
  "⚖️ Sıklet: Hafif sıkletler hızlı ve dayanıklıdır, ağır sıkletler sert vurur ama çabuk yorulur.": "⚖️ Весовая категория: лёгкие веса быстрые и выносливые, тяжёлые бьют сильно, но быстро устают.",
  "🥋 Branş: En önemli seçim. Güçlü ve zayıf yönlerini, dolayısıyla nasıl dövüşeceğini belirler.": "🥋 База: самый важный выбор. Определяет сильные и слабые стороны, а значит, и то, как вы деретесь.",
  "📖 Hikâye: Kendin yazabilir ya da oyuna yazdırabilirsin.": "📖 История: напишите сами или доверьте игре.",
  "🎲 Zar: Son adımda istatistiklerin zarla belirlenir. Beğenmezsen 2 kez yeniden atabilirsin.": "🎲 Кубики: на последнем шаге характеристики выпадают случайно. Не нравится? Можно перебросить дважды.",
  "Gelişim Puanı": "Очки навыков",
  "Kariyere 3 puanla başlarsın. Her antrenman kampı 1-3 puan verir (yoğunluk, yaş, kamp yeri, hoca ve kadro kalitesine bağlı). Kampın odak alanı ayrıca +1-3 gelişir.": "Карьеру вы начинаете с 3 очков. Каждый лагерь даёт 1-3 очка (в зависимости от интенсивности, возраста, места, тренера и качества штаба). Упор лагеря тоже растёт на +1-3.",
  "Dövüşler de puan verir: galibiyet 2, bitiriş +1, bonus +1, kemer +1. Mağlubiyet ve beraberlik 1 puan.": "Очки дают и бои: победа 2, досрочная +1, бонус +1, пояс +1. Поражение и ничья — 1 очко.",
  "📅 Bir dövüş döngüsü (kamp + toparlanma) yaklaşık 90-100 gün sürer. Yılda 3-4 kez dövüşürsün; her karar önemli.": "📅 Цикл боя (лагерь + восстановление) занимает около 90-100 дней. Вы дерётесь 3-4 раза в год; каждое решение важно.",
  "Puanı istediğin istatistiğe harcarsın. 50’ye kadar +1 için 1 puan, 70’e kadar 2, 85’e kadar 3, sonrası 4 puan gerekir.": "Тратьте очки на любую характеристику. До 50 +1 стоит 1 очко; до 70 — 2; до 85 — 3; дальше — 4 очка.",
  "Kamp sonunda tartıdan önce, dövüş sonrasında ya da Kariyer ekranındaki GELİŞİM sekmesinden harcayabilirsin.": "Тратить можно перед взвешиванием в конце лагеря, после боя или во вкладке «РАЗВИТИЕ» экрана карьеры.",
  "Nasıl Oynanır?": "Как играть",
  "1️⃣ Rakip seç. Bölgesel aşamada sen seçersin, büyük organizasyonlarda rakibi organizasyon dayatır.": "1️⃣ Выберите соперника. На региональном этапе выбираете вы; в крупных лигах его назначают.",
  "2️⃣ Kamp: odak alanı, oyun planı, yoğunluk, kilo verme ve basın toplantısı. Oyun planı rakibin zaafına denk gelirse kafeste büyük avantaj sağlar.": "2️⃣ Лагерь: упор, план на бой, интенсивность, сгонка веса и пресс-конференция. План, бьющий в слабость соперника, даёт большое преимущество в октагоне.",
  "3️⃣ Dövüş: her raunt taktik seçersin. Kritik anlarda (rakip sarsıldı, submission yakalandı) hızlı karar verirsin.": "3️⃣ Бой: выбирайте тактику каждый раунд. В критические моменты (соперник потрясён, пойман сабмишен) решайте быстро.",
  "4️⃣ Sonrası: bonuslar, röportaj, sıralama, kontrat teklifleri ve dövüşler arası olaylar.": "4️⃣ Потом: бонусы, интервью, рейтинг, контракты и события между боями.",
  "🏆 Yol: Amatör → Bölgesel (CFC, Hexagon) → Büyük (PFC, ZEN, VIP) → DWCS veya kısa haber → UCC kemeri.": "🏆 Путь: Любители → Региональные (CFC, Hexagon) → Крупные (PFC, ZEN, VIP) → DWCS или срочная замена → пояс UCC.",
