  "{0} sokaklarından çıktı; {1} yaşında {2} galibiyete ulaştı, {3} bitiriş.": "Вышел с улиц {0}; к {1} годам — {2} побед и {3} досрочных.",
  "HOCAN · {0}": "ВАШ ТРЕНЕР · {0}",
  "ANLADIM": "ПОНЯТНО",
  "İpuçlarını kapat": "Отключить подсказки",
  "Burası senin köşen": "Это ваш угол",
  "Üstte paran, sağlığın ve popülerliğin var. Hazır olduğunda “DÖVÜŞ AYARLA” ile rakibini seç. Aradaki haftalarda mağaza, sosyal medya ve gece hayatı seni bekliyor; ama unutma, her şeyin bir bedeli var.": "Вверху — деньги, здоровье и популярность. Когда будете готовы, выберите соперника через «НАЗНАЧИТЬ БОЙ». В неделях между боями ждут магазин, соцсети и ночная жизнь; но помните, у всего есть цена.",
  "Gelişim puanları": "Очки навыков",
  "Kamplardan ve dövüşlerden puan kazanırsın, burada istatistiklerine dağıtırsın. 50’den sonra her artış pahalanır; zayıf yönünü kapatmak çoğu zaman daha akıllıcadır.": "Очки даются за лагеря и бои, здесь вы распределяете их по характеристикам. После 50 каждое очко дороже; закрыть слабое место обычно разумнее.",
  "Rakibini seç": "Выберите соперника",
  "Her rakibin gücü ve zayıf yönü yazıyor. Kolay rakip güvenlidir ama az kazandırır; riskli bir rakibi yenersen sıralamada büyük bir sıçrama yaparsın.": "У каждого соперника указаны сила и слабость. Лёгкий соперник — надёжно, но приносит мало; победите рискованного — и сделаете большой скачок в рейтинге.",
  "Kamp başlıyor": "Лагерь начинается",
  "Önce kampın süresini seç. Uzun kamp daha çok geliştirir ama pahalıdır ve yorar. Kamptan önceki boş haftalarda teknik çalışabilir, spar yapabilirsin.": "Сначала выберите длину лагеря. Длинный развивает сильнее, но дорог и изматывает. В свободные недели до лагеря можно отрабатывать технику и спарринговать.",
  "Oyun planı": "План на бой",
  "Rakibin zayıf yönüne uyan plan, dövüşte etkisini ikiye katlar. Keşif raporuna bak ve planını ona göre seç.": "План, бьющий в слабость соперника, удваивает эффект в бою. Изучите отчёт разведки и выберите план.",
  "Burun buruna": "Лицом к лицу",
  "Tartıdan sonra rakibinle yüz yüze geleceksin. Takındığın tavır onun moralini bozabilir ya da sana pahalıya patlayabilir.": "После взвешивания вы сойдётесь с соперником лицом к лицу. Ваше поведение может сломить его дух — или дорого вам обойтись.",
  "Her raundun başında bir taktik seç, dövüş kendi akar. Rakip sarsıldığında ya da bir submission fırsatında hızlı karar vermen gerekir. Kondisyonunu izle: yorulursan her şey zorlaşır.": "В начале каждого раунда выберите тактику, дальше бой идёт сам. Когда соперник потрясён или открывается сабмишен, решать нужно быстро. Следите за выносливостью: устанете — всё станет сложнее.",
  "Dövüş bitti": "Бой окончен",
  "Mikrofon sende: röportajdaki sözlerin popülerliğini etkiler. Kazandığın puanları GELİŞİM sekmesinde harca. Güzel bir galibiyet mi? Paylaş, herkes görsün!": "Микрофон у вас: слова в интервью влияют на популярность. Потратьте заработанные очки во вкладке «РАЗВИТИЕ». Яркая победа? Поделитесь, пусть все увидят!",
