  "Şans bir kez güler. Üçüncü maçta görüşürüz.": "Удача улыбается лишь раз. До следующей встречи.",
  "⚔️ Ezeli rakibinle berabere. Aranızdaki seri: {0}. Kimse tatmin olmadı.": "⚔️ Ничья с заклятым соперником. Счёт: {0}. Никто не доволен.",
