  "İpucu: Hakarete espriyle, övünmeye sert, alaya soğukkanlı cevap ver.": "Совет: на оскорбление отвечай шуткой, на хвастовство жёстко, на насмешку хладнокровно.",
  "{0} mi? Bu kafese değil, kreşe gitmeli.": "{0}? Тебе в детский сад, а не в клетку.",
  "Şu surata bakın: daha önce çok dayak yediği belli.": "Посмотрите на это лицо: видно, что его много били.",
  "Onun antrenmanlarını izledim. Annem daha sert vuruyor.": "Я видел твои тренировки. Моя мама бьёт сильнее.",
  "Tek yeteneği basın toplantısında uyumamak.": "Твой единственный талант — не уснуть на пресс-конференции.",
  "Ben bu sıkletin kralıyım. Onu ilk rauntta uyutacağım, yazın bir kenara.": "Я король этого веса. Усыплю тебя в первом раунде, запиши.",
  "Bana rakip bulamıyorlar, o yüzden bunu getirdiler.": "Мне не могут найти соперника, вот и привели это.",
  "Kemeri şimdiden evime astım. Bu maç sadece formalite.": "Пояс уже висит у меня дома. Этот бой — формальность.",
  "Benim ısınmam onun bütün kariyeri kadar sürüyor.": "Моя разминка длится дольше всей твоей карьеры.",
  "Hahaha! {0} titriyor bakın, ellerine bakın!": "Ха-ха-ха! {0}, у тебя руки трясутся, посмотрите!",
  "Kilo verirken ağladığını duydum. Çok tatlı.": "Говорят, ты плачешь на сгонке веса. Как мило.",
  "Gözlerime bakamıyor bile. Daha şimdiden kaybetti.": "Даже в глаза мне посмотреть не можешь. Ты уже проиграл бой.",
  "Hocası bile onun yerine utanıyor, şu hâline bakın.": "Даже твой тренер за тебя краснеет, посмотрите.",
  "Kreş mi? Doğru, cumartesi seni orada bebek gibi uyutacağım.": "Детский сад? Точно, в субботу уложу тебя спать, как младенца.",
  "Annenle antrenman yapıyorsan bana da numarasını ver, belki bir şey öğrenirim.": "Если тренируешься с мамой, дай её номер, может, чему-то научусь.",
  "Konuş, konuş. Cumartesi gecesi konuşamayacaksın.": "Болтай, болтай. В субботу вечером не сможешь.",
  "Laflar ucuz. Kafeste görüşürüz.": "Слова ничего не стоят. Увидимся в клетке.",
  "Bir daha ağzını açarsan burada dağıtırım seni!": "Ещё раз откроешь рот — разнесу тебя прямо здесь!",
  "Kapa çeneni yoksa ben kapatırım!": "Закрой рот, или я его закрою!",
  "Kral mı? Son üç maçında yere kaç kez düştüğünü sayalım mı?": "Король? Посчитаем, сколько раз ты падал в последних трёх боях?",
  "Kemeri evine asmışsın, güzel. Ben gelip alacağım.": "Пояс у тебя дома? Отлично. Приду и заберу.",
  "İlk rauntta uyutacakmış… herhalde bu konuşmasıyla.": "Усыпит в первом раунде… разве что этой речью.",
  "Tamam. Görürüz.": "Ладно. Посмотрим.",
  "Saygı duyuyorum, iyi şanslar.": "Уважаю. Удачи.",
  "Gülmeye devam et. Son gülen iyi güler.": "Смейся дальше. Хорошо смеётся тот, кто смеётся последним.",
  "Ellerim titremiyor, sadece seni beklemekten sıkıldılar.": "Руки не трясутся, им просто скучно тебя ждать.",
  "Gülüyor musun? Cumartesi gülemeyeceksin!": "Смеёшься? В субботу не будешь смеяться!",
  "Bir daha bana gülersen sahnede kavga çıkar!": "Ещё раз засмеёшься — будет драка прямо на сцене!",
  "Hahaha, evet çok komiksin… dur, bunu anneme de anlatayım.": "Ха-ха, да, очень смешно… погоди, маме расскажу.",
