  "Rakibi oku": "Читай соперника",
  "Rakip saldırı hazırlarken başında küçülen bir halka çıkar. Halka ALTIN olunca KAÇ'a bas, sonra hemen vur: kontra vuruşların çift hasar yapar.": "Когда соперник замахивается, вокруг его головы сжимается кольцо. Стало ЗОЛОТЫМ — жми УЙТИ и сразу бей: контратаки наносят двойной урон.",
  "Vur ve kes": "Бей и прерывай",
  "JAB hızlı ve ucuz, DİREKT ve TEKME ağırdır. Rakip hazırlanırken DİREKT ya da TEKME atarsan saldırısını kesersin. Sarı çubuk nefesin: bitince vuruşların zayıflar.": "ДЖЕБ быстрый и дешёвый, ПРЯМОЙ и УДАР НОГОЙ тяжёлые. Брось ПРЯМОЙ или УДАР НОГОЙ во время замаха — прервёшь атаку. Жёлтая полоса — дыхание: кончится, удары ослабнут.",
  "İNDİR ile takedown dene; rakip ⬇️ ile dalarsa KAÇ ile sprawl yap. Yerde düğmeler değişir: üstteyken vur ve submission ara, alttayken 🔒 görünce hemen KURTUL.": "Пробуй ПРОХОД; если он ныряет с ⬇️ — защищайся кнопкой УЙТИ. В партере кнопки меняются: сверху бей и ищи болевой, снизу при 🔒 сразу ВЫРЫВАЙСЯ.",
