  "Son 48 saat: kilonu ver": "Последние 48 часов: сгони вес",
  "🏆 Yükseliş Grand Prix'i daveti geldi! 8 amatör, tek kupa: şampiyon ve finalist profesyonel kapıyı açar.": "🏆 Приглашение на Гран-при «Восхождение»! 8 любителей, один кубок: чемпион и финалист открывают дверь в профи.",
