  "🏆 Yükseliş Grand Prix'ini kazandın! Organizasyonlar sıraya girdi: profesyonel kapı ardına kadar açık.": "🏆 Ты выиграл Гран-при «Восхождение»! Лиги выстроились в очередь: дверь в профи открыта настежь.",
  "🥈 Finalde kaybettin ama herkes seni izledi. Profesyonel organizasyonlar seni kadrosunda istiyor!": "🥈 Ты проиграл финал, но все тебя видели. Профессиональные лиги хотят тебя в составе!",
  "YÜKSELİŞ GRAND PRIX'İ DAVETİ": "ПРИГЛАШЕНИЕ: ГРАН-ПРИ «ВОСХОЖДЕНИЕ»",
  "Profesyonelliğe giden yolda vitrin: 8 amatör, üç maç (çeyrek final, yarı final, final). Kaybeden elenir. Şampiyon {0} ve kupayı alır; şampiyon da finalist de doğrudan profesyonel teklif alır. Davet yalnızca bir kez gelir.": "Витрина на пути в профи: 8 любителей, три боя (четвертьфинал, полуфинал, финал). Проиграл — выбыл. Чемпион получает {0} и кубок; и чемпион, и финалист сразу получают профессиональные предложения. Приглашение приходит только раз.",
