  "Yonca desenli şapka": "Шляпа с трилистником",
  "Eyfel anahtarlığı": "Брелок с Эйфелевой башней",
  "Duvar parçası": "Кусок Стены",
  "Kale kartpostalı": "Открытка с замком",
  "Ahşap Dala atı": "Деревянная далекарлийская лошадка",
  "Tahta takunya": "Деревянные сабо",
  "Kum şişesinde çöl manzarası": "Пустыня в бутылке с песком",
  "Muay Thai mongkolu": "Монгкон для муай-тай",
  "Jeepney maketi": "Модель джипни",
  "İkiz kuleler maketi": "Модель башен-близнецов",
  "Maneki-neko kedisi": "Кошка манэки-нэко",
  "El dokuması kumaş": "Ткань ручной работы",
  "Boncuklu bileklik": "Браслет из бисера",
  "Kanguru peluşu": "Плюшевый кенгуру",
  "Maori oyması kolye": "Резной кулон маори",
  "Annenin bahçesinde çekilmiş bir fotoğraf. Arkasında “Her zaman buradayız.” yazıyor.": "Фото в мамином саду. На обороте: «Мы всегда здесь».",
  "Gün doğumunda yüzlerce balon. Hayatında ilk kez kafan bu kadar sessizdi.": "Сотни шаров на рассвете. Впервые в жизни в голове было так тихо.",
  "Açık büfeden bir tabak. Arkasına antrenörün “Bunu görmedim.” yazmış.": "Тарелка со шведского стола. Тренер подписал: «Я этого не видел».",
  "Sörf tahtasıyla kumsalda. İlk dalgada düştün, onuncuda ayaktaydın.": "На пляже с доской. Упал на первой волне, встал на десятой.",
  "Bir gökdelenin tepesinden şehir. Ünlülerle çekilmiş fotoğraflar telefonunda.": "Город с вершины небоскрёба. Телефон полон фото со знаменитостями.",
  "Su üstü villanın terası. İki hafta boyunca telefona bakmadın.": "Терраса виллы над водой. Две недели ты не смотрел в телефон.",
  "Yarış pistinin kenarında bir yat. Kimin partisi olduğunu hâlâ bilmiyorsun.": "Яхта у гоночной трассы. Ты до сих пор не знаешь, чья это была вечеринка.",
  "Bali": "Бали",
  "Dubai": "Дубай",
  "Maldivler": "Мальдивы",
  "Monako": "Монако",
  "{0}. hafta": "{0}-я неделя",
