  "Bir deniz subayına aitmiş. Kadranı zamanla kahveye dönmüş.": "Принадлежали морскому офицеру. Циферблат со временем стал коричневым.",
  "Yarışçı Kronografı": "Гоночный хронограф",
  "Efsane bir pilotun bileğindeymiş. Koleksiyoncular peşinde.": "Были на руке легендарного гонщика. Коллекционеры охотятся за ними.",
  "Tourbillon Platin Saat": "Платиновые часы с турбийоном",
  "Yılda yalnızca 12 tane üretiliyor. El işi, 300 parça.": "Всего 12 штук в год. Ручная работа, 300 деталей.",
  "Osmanlı Dönemi Cep Saati": "Карманные часы османской эпохи",
  "Kapağında tuğra işlemeli. Müzelerin bile istediği bir parça.": "На крышке выгравирована тугра. Даже музеи хотят его.",
  "1967 Klasik Kupe": "Классическое купе 1967 года",
  "Fabrika çıkışı kırmızı, orijinal motor. Pazar sabahları sahil yolu.": "Заводской красный, родной мотор. Воскресные утра на прибрежной дороге.",
  "Efsane Ralli Arabası": "Легендарный раллийный автомобиль",
  "Üç şampiyonluk kazanmış. Çamur izleri bilerek temizlenmemiş.": "Выиграл три чемпионата. Грязь специально не отмывали.",
