  "{0} antrenmandan sonra seni kenara çekti: “Beni dinlemiyorsun. Böyle devam edeceksek yollarımızı ayıralım.”": "После тренировки {0} отвёл тебя в сторону: «Ты меня не слушаешь. Если так пойдёт и дальше, нам лучше расстаться».",
  "Özür dile, yeniden başlayalım": "Извиниться и начать заново",
  "Maaşına zam yap ({0})": "Повысить ему зарплату ({0})",
  "Yollarınızı ayırın": "Расстаться",
  "Gururunu yuttun. {0} başını salladı: “Yarın sabah altıda.” Bağ toparlanıyor, motivasyon -1.": "Ты проглотил гордость. {0} кивнул: «Завтра в шесть». Связь восстанавливается, мотивация -1.",
  "Zam iyi geldi ama asıl önemli olan oturup konuşmanızdı. Bağ güçlendi.": "Прибавка помогла, но главное — вы сели и поговорили. Связь окрепла.",
  "{0} ile yollarınız ayrıldı. Yeni hocan {1}. Sıfırdan bir güven kurmanız gerekecek. Motivasyon -1.": "Вы с {0} расстались. Новый тренер — {1}. Доверие придётся строить с нуля. Мотивация -1.",
  "🫂 Bir Baba Gibi": "🫂 Как отец",
  "Gece salonda yalnız kaldınız. {0} eski bir fotoğraf çıkardı: ilk antrenmanın, eldivenler elinden büyük. “O gün kapıdan girdiğinde ne olacağını biliyordum,” dedi.": "Поздно вечером, одни в зале, {0} достал старое фото: твоя первая тренировка, перчатки больше рук. «В тот день, когда ты вошёл в эту дверь, я всё понял», — сказал он.",
  "Sarıl": "Обнять",
  "“Her şeyi sana borçluyum.”": "«Я всем обязан тебе».",
  "{0} ile ilk antrenman fotoğrafı": "Фото первой тренировки с {0}",
  "Eldivenler elinden büyük. Arkasında hocanın el yazısı: “Bir gün.”": "Перчатки больше рук. На обороте почерком тренера: «Однажды».",
  "Uzun süre konuşmadınız. Gerek yoktu. Motivasyon +2.": "Вы долго молчали. Слова были не нужны. Мотивация +2.",
  "“Hayır,” dedi, “her şeyi kendine borçlusun. Ben sadece kapıyı açtım.” Motivasyon +2.": "«Нет, — сказал он, — ты всем обязан себе. Я лишь открыл дверь». Мотивация +2.",
  "📨 Rakip Kampın Teklifi": "📨 Предложение чужого лагеря",
  "Büyük bir salon {0} hocana baş antrenörlük teklif etmiş, maaşı iki katı. Sana söylemedi; sen başkasından duydun.": "Крупный зал предложил твоему тренеру {0} должность главного тренера с двойной зарплатой. Он тебе не сказал — ты узнал от других.",
  "Ona zam yap ve kalmasını iste ({0})": "Повысить зарплату и попросить остаться ({0})",
  "Onu tebrik et, gitmesine izin ver": "Поздравить и отпустить",
  "Sessiz kal, kararı ona bırak": "Промолчать и оставить решение ему",
  "{0} teklifi reddetti: “Benim dövüşçüm burada.” Bağ çok güçlendi.": "{0} отказался: «Мой боец здесь». Связь стала гораздо крепче.",
  "{0} gözleri dolu gitti, giderken seni yeni hocan {1} ile tanıştırdı. Motivasyon +1.": "{0} ушёл со слезами на глазах, напоследок познакомив тебя с новым тренером {1}. Мотивация +1.",
  "{0} kaldı. “Sana sormadan karar vermem gerekirdi, ama burası benim evim,” dedi.": "{0} остался. «Надо было решить, не спрашивая тебя, но это мой дом», — сказал он.",
  "{0} teklifi kabul etti. Yeni hocan {1}.": "{0} принял предложение. Твой новый тренер — {1}.",
  "🏥 Hocanın Sağlığı": "🏥 Здоровье тренера",
  "{0} birkaç haftadır öksürüyordu. Doktorlar dinlenmesini söyledi ama o kampı bırakmak istemiyor.": "{0} уже несколько недель кашляет. Врачи велели отдыхать, но он не хочет покидать лагерь.",
  "Zorla tatile gönder, kampı asistan yönetsin": "Отправить отдыхать, лагерь поведёт ассистент",
  "Onun kararına saygı duy": "Уважать его решение",
  "Önce kızdı, sonra teşekkür etti. Bir ay sonra eskisinden dinç döndü. Bağ güçlendi.": "Сначала злился, потом благодарил. Через месяц вернулся бодрее прежнего. Связь окрепла.",
  "Kampı yönetti ama her gece onu merak ettin. Motivasyon -1.": "Он провёл лагерь, но ты каждую ночь за него переживал. Мотивация -1.",
  "🕊️ Hocanın Vedası": "🕊️ Прощание тренера",
  "{0} seni salonun ortasına çağırdı: “Yaşlandım evlat. Sana öğretebileceğim her şeyi öğrettim.” Yerine kendi asistanını önerdi.": "{0} позвал тебя в центр зала: «Я старею, сынок. Я научил тебя всему, что знал». И предложил вместо себя своего ассистента.",
  "Son bir antrenman yapın": "Провести последнюю тренировку",
