  "🎬 Film Teklifi": "🎬 Предложение сняться в кино",
  "Bir yapımcı seni “{0}” adlı aksiyon filminde kötü adam olarak istiyor. Çekimler üç hafta, Hollywood'dan bir yönetmen.": "Продюсер хочет видеть тебя злодеем в боевике «{0}». Три недели съёмок, режиссёр из Голливуда.",
  "Sette herkes senden korktu, sonra sevdi. Fragman bir günde 20 milyon izlendi.": "На площадке все тебя боялись, а потом полюбили. Трейлер за день набрал 20 миллионов просмотров.",
  "🎥 Belgesel Teklifi": "🎥 Предложение документального фильма",
  "Bir yayın platformu senin hayatını anlatan bir belgesel çekmek istiyor. Kamera ekibi bir sonraki kampın boyunca peşinde olacak; memleketine, ailene de gidecekler.": "Стриминговая платформа хочет снять документальный фильм о твоей жизни. Съёмочная группа будет с тобой весь следующий лагерь и съездит к тебе на родину, к семье.",
  "Kafesten Kemere": "Из клетки к поясу",
  "Kamera her şeyi çekti: sabah koşularını, kesimin zor anlarını, annenin mutfağını. İzleyiciler seni tanıdı.": "Камера сняла всё: утренние пробежки, тяжёлые моменты сгонки, мамину кухню. Зрители узнали тебя.",
  "📺 Reklam Yüzü": "📺 Лицо рекламы",
  "{0} yeni kampanyasının yüzü olmanı istiyor. Bir günlük çekim, ülke çapında billboard.": "{0} хочет, чтобы ты стал лицом новой кампании. Один съёмочный день, билборды по всей стране.",
  "Şehrin her köşesinde yüzün var. Annen her billboard'un fotoğrafını çekiyor.": "Твоё лицо на каждом углу. Мама фотографирует каждый билборд.",
  "🎙️ Talk Show Daveti": "🎙️ Приглашение на ток-шоу",
  "“{0}” programı seni konuk olarak çağırdı. Sunucu ünlü, şaka kaldırırsa salon seninle.": "Программа «{0}» пригласила тебя в гости. Ведущий знаменит: умеешь держать шутку — зал твой.",
  "Sunucuya canlı yayında armbar gösterdin. Klip her yerde.": "Ты показал ведущему рычаг локтя в прямом эфире. Клип повсюду.",
  "📰 Dergi Kapağı": "📰 Обложка журнала",
  "{0} dergisi seni kapağa koymak istiyor. Bir günlük çekim, büyük bir röportaj.": "Журнал {0} хочет тебя на обложку. Один день съёмок и большое интервью.",
  "Kapak büfelerde tükendi. Bir kopyası salonun duvarında.": "Номер раскупили в киосках. Один экземпляр висит в зале.",
  "📺 Dizi Konuk Rolü": "📺 Камео в сериале",
  "Sevilen dizi “{0}” bir bölümde seni kendini oynaman için istiyor. İki hafta çekim.": "Популярный сериал «{0}» зовёт тебя сыграть самого себя в одной серии. Две недели съёмок.",
  "Sahnen sosyal medyada dolaştı. Senaristler “bir sezon daha gel” diyor.": "Твоя сцена разлетелась по соцсетям. Сценаристы зовут тебя ещё на сезон.",
