  "Gelişim çağı": "Период роста",
  "Vücudun hızla öğreniyor: kamptan en çok gelişimi bu yaşlarda alırsın.": "Тело быстро учится: в этом возрасте лагеря дают больше всего.",
  "Zirve yılları": "Пиковые годы",
  "Hız, güç ve kondisyon en iyi hâlinde. Kemer için en doğru zaman.": "Скорость, сила и выносливость на пике. Самое время за поясом.",
  "Gelişim yavaşlıyor ama kafes zekân her maçla artıyor.": "Прогресс замедляется, но боевой интеллект растёт с каждым боем.",
  "Gün batımı": "Закат",
  "Her yıl hız ve çene biraz düşer, IQ artar. Akıllı dövüşmek zorundasın.": "Каждый год скорость и подбородок немного слабеют, а IQ растёт. Придётся драться с умом.",
  "Yaşın, izlerin ve günlük rutinin. Küçük seçimler, uzun bir kariyerde büyük fark yaratır.": "Твой возраст, твои травмы и распорядок дня. Мелочи решают многое в долгой карьере.",
