  "Her iz kampta sakatlık riskini biraz artırır. Fizyoterapist bu riski azaltır.": "Каждый след немного повышает риск травмы в лагере. Физиотерапевт снижает этот риск.",
  "Vücudunda kalıcı iz yok. Ağır sakatlıklar iyileşirken bazen iz bırakır.": "Стойких следов нет. Тяжёлые травмы иногда оставляют след при заживлении.",
