  "Gece düzenlemek için kontratı süren en az 4 dövüşçü gerekiyor. Keşif sekmesinden imzala.": "Для вечера нужно минимум 4 бойца с действующим контрактом. Подпиши на вкладке «Скаутинг».",
  "Aktif kariyerde her maçından sonra bir gece düzenleyebilirsin.": "Пока ты выступаешь, можно проводить один вечер после каждого своего боя.",
  "Geceyi düzenle": "Провести вечер",
  "{0} dövüşçünün kontratı bitti: yenile ya da bırak.": "У {0} бойцов закончился контракт: продли или отпусти.",
