  "BIRAK": "ОТПУСТИТЬ",
  "Kadron boş. Keşif sekmesinden dövüşçü imzala.": "Состав пуст. Подпиши бойцов на вкладке «Скаутинг».",
  "Yeni adaylar · {0}": "Новые кандидаты · {0}",
  "İmza parası, maç başı ücretin iki katıdır. Kontrat 4 maç sürer. Her geceden sonra yeni adaylar gelir.": "Подписной бонус — двойной гонорар за бой. Контракт на 4 боя. После каждого вечера приходят новые кандидаты.",
