  "KAMP SEANSI · İSTEĞE BAĞLI": "СЕАНС ЛАГЕРЯ · ПО ЖЕЛАНИЮ",
  "{0}: 15 saniyelik bir mini oyun. İyi oynarsan bütün kamp daha verimli geçer, sakatlık riski düşer.": "{0}: мини-игра на 15 секунд. Сыграешь хорошо — весь лагерь будет продуктивнее, а риск травмы ниже.",
