  "Kamp hazır. Haftalar kendiliğinden akacak; bir karar gerektiğinde duracak.": "Лагерь готов. Недели пойдут сами и остановятся, когда понадобится решение.",
  "Sparda sert bir darbe aldın; kaburgaların sızlıyor. {0} kararı sana bırakıyor.": "Ты пропустил сильный удар в спарринге, болят рёбра. {0} оставляет решение тебе.",
