  "{0} kampın gidişatından memnun ve gece seansları eklemek istiyor.": "{0} доволен ходом лагеря и хочет добавить вечерние тренировки.",
  "Ekstra seansı ekle": "Добавить тренировки",
  "Dinlenmeyi tercih et": "Выбрать отдых",
  "Diyetisyen tartıyı erken düşünmeni öneriyor: şimdiden kalori kesersen son 48 saat kolaylaşır.": "Диетолог советует заранее думать о взвешивании: урежешь калории сейчас — последние 48 часов дадутся легче.",
  "Diyete şimdi başla": "Сесть на диету сейчас",
  "Önce kampa odaklan": "Сначала сосредоточиться на лагере",
  "Büyük bir spor kanalı kamptan röportaj istiyor. Bir gün sürer.": "Крупный спортивный канал просит интервью из лагеря. Это займёт день.",
  "Röportajı ver": "Дать интервью",
  "Kampı koru": "Сберечь лагерь",
  "Ünlü bir antrenör bir haftalığına kampına katılabilir. Ücreti ${0}.": "Известный тренер может присоединиться к лагерю на неделю. Гонорар: ${0}.",
  "Davet et (${0})": "Пригласить (${0})",
  "Gerek yok": "Не нужно",
  "İki gün buz ve masaj. Biraz yavaşladın ama vücudun teşekkür ediyor.": "Два дня льда и массажа. Ты немного сбавил, но тело благодарно.",
  "Devam ettin. Hocan seni izliyor; bir şey olursa erken fark edecek.": "Ты продолжил. Тренер следит и вовремя заметит проблему.",
  "Gece seansları zorladı ama verimli geçti (sağlık -6).": "Вечерние тренировки были тяжёлыми, но полезными (здоровье -6).",
  "Dinlenmeyi seçtin; enerjin yerinde (sağlık +4).": "Ты выбрал отдых, энергии хватает (здоровье +4).",
  "Tabağın küçüldü, keyfin biraz kaçtı (motivasyon -1) ama tartı haftası daha rahat geçecek.": "Тарелки поменьше, настроение похуже (мотивация -1), зато неделя взвешивания пройдёт легче.",
  "Kilo işini son haftaya bıraktın.": "Ты оставил вес на последнюю неделю.",
  "Röportaj çok izlendi (popülerlik +2); bir antrenman günü kaçtı.": "Интервью много смотрели (популярность +2), но ты потерял день тренировок.",
  "Kapıyı kapattın, odak tamamen kampta.": "Ты закрыл дверь — всё внимание лагерю.",
  "Misafir antrenör bir haftada kafanda yeni kapılar açtı. Kamp daha verimli.": "За неделю приглашённый тренер открыл тебе новые горизонты. Лагерь эффективнее.",
  "Kendi ekibinle devam ettin.": "Ты продолжил со своей командой.",
