  "Dart": "Дартс",
  "Üç atış. Nişangâh kayarken tam ortaya geldiğinde dokun. Hızın ne kadar yüksekse nişangâh o kadar yavaş kayar.": "Три броска. Нажми, когда прицел окажется в центре. Чем выше твоя скорость, тем медленнее он движется.",
  "Yumruk makinesi": "Силомер",
  "Güç çubuğu dolup boşalırken zirvede vur. Vuruş gücün skoru büyütür.": "Бей, когда шкала на пике. Ударная мощь увеличивает счёт.",
