  "Randevu · kulüp · oyun salonu": "Свидания · клуб · игровой зал",
  "Neon ışıklar, yüksek müzik, pahalı içkiler. Kafanı dağıtır… ama bedeli var.": "Неон, громкая музыка, дорогие напитки. Голова проясняется… но это не бесплатно.",
  "ŞEHİRDE GECE GEZMESİ": "НОЧНАЯ ПРОГУЛКА ПО ГОРОДУ",
  "Uykusuz geceler birikir, haftalar geçtikçe azalır. Çok sık çıkarsan hastalanma ihtimalin artar.": "Бессонные ночи накапливаются и проходят со временем. Слишком часто гуляешь — чаще болеешь.",
  "GECE KULÜBÜ": "НОЧНОЙ КЛУБ",
