  "Bir içki, biraz müzik. Az masraf, az risk.": "Один напиток, немного музыки. Мало затрат, мало риска.",
  "VIP loca, sabaha kadar": "VIP-ложа до утра",
  "Gece uzar, uyku kısalır. Hastalanma riski yüksek.": "Ночь длинная, сон короткий. Высокий риск заболеть.",
  "Yüksek müzik, kalabalık. Kafanı dağıttın.": "Громкая музыка, толпа. Ты отвлёкся.",
  "VIP locada gece uzadı… Sabah salona geç kaldın.": "Ночь в VIP-ложе затянулась… в зал ты опоздал.",
