  "Reklamla": "За рекламу",
  "Anında": "Сразу",
  "Kariyer yuvası": "Слоты карьеры",
  "Conor + 1. bölümler": "Конор + первые главы",
  "{0} efsanenin tamamı": "Все {0} легенд",
  "Altın Seri ve Şampiyon çerçevesi": "Золотая серия и рамка чемпиона",
  "Şampiyon ol · {0}": "Стать чемпионом · {0}",
  "BUGÜN 3 REKLAM İZLEDİN": "СЕГОДНЯ ТЫ ПОСМОТРЕЛ 3 РЕКЛАМЫ",
  "Şampiyon Paketi ile bütün ödüller reklamsız ve anında gelir. Tek seferlik alım, abonelik yok.": "С Набором чемпиона все награды приходят сразу и без рекламы. Разовая покупка, без подписки.",
  "BÜTÜN YUVALAR DOLU": "ВСЕ СЛОТЫ ЗАНЯТЫ",
  "Şampiyon Paketi ile 5 kariyer yuvası: yeni bir hikâyeye başlamak için eskisini silmen gerekmez.": "Набор чемпиона даёт 5 слотов карьеры: не нужно удалять старую историю ради новой.",
  "BİR ŞAMPİYONA YAKIŞIR PAKET": "НАБОР, ДОСТОЙНЫЙ ЧЕМПИОНА",
  "Kemeri kazandın. Şampiyon Paketi ile oyunun bütün ekstralarını aç.": "Пояс твой. Открой все дополнения игры с Набором чемпиона.",
  "👑 Şampiyon Paketi ile reklamsız, anında": "👑 Без рекламы и сразу с Набором чемпиона",
  "👑 ŞAMPİYON PAKETİ": "👑 НАБОР ЧЕМПИОНА",
  "İstediğin iki dövüşçü, istediğin sıklet, istediğin kadar maç. Kendi efsanelerini de efsanelere karşı dövüştür.": "Любые два бойца, любой вес, сколько угодно боёв. Выставь и своих легенд против легенд.",
  "Hayalî Maç Stüdyosu": "Студия боёв мечты",
  "Rövanş": "Реванш",
  "Yeni eşleşme": "Новый поединок",
  "Hayalî Maçlar'a dön": "Назад к Боям мечты",
  "HAYALÎ MAÇ STÜDYOSU": "СТУДИЯ БОЁВ МЕЧТЫ",
  "Kimi yöneteceksin?": "Кем будешь управлять?",
  "Rakibini seç.": "Выбери соперника.",
