  "O gece bir türlü aklından çıkmadı. Boyun kilidi, susan salon, kafesin üstünden atlayanlar.": "Та ночь не выходила из головы. Удушающий, затихший зал, люди, прыгающие через клетку.",
  "Ama ya her şey başka türlü olsaydı? Ya rövanş gerçekten yapılsaydı?": "А если бы всё сложилось иначе? Если бы реванш действительно состоялся?",
  "Khabir Nurmagaliev hâlâ kemerin sahibi. Bu kez onu ayakta tutacak, mesafeyi sen belirleyeceksin.": "Хабир Нурмагалиев всё ещё чемпион. На этот раз ты удержишь его в стойке и сам выберешь дистанцию.",
  "Khabir Nurmagaliev'i yen": "Победи Хабира Нурмагалиева",
  "Hafif sıklete dön: Nurmagaliev kemerin sahibi olarak orada bekliyor.": "Вернись в лёгкий вес: Нурмагалиев ждёт там с поясом.",
  "Hafif sıklet kemerini al": "Завоюй пояс в лёгком весе",
  "Rövanş PPV payı": "Доля PPV реванша",
  "🔀 Tarih yeniden yazıldı: rövanşı kazanan sensin.": "🔀 История переписана: реванш за тобой.",
  "Hiç Sorun Çıkarmasaydı": "Если бы не было скандалов",
  "Cezalar, kayıp yıllar, manşetlere düşen gece yarısı haberleri… Hiçbiri yaşanmasaydı?": "Дисквалификации, потерянные годы, ночные заголовки… А если бы ничего этого не было?",
  "Bu kez erken yatıyorsun, salona ilk sen giriyorsun, telefonunu kapatıyorsun.": "На этот раз ты рано ложишься, первым приходишь в зал и выключаешь телефон.",
  "Soru basit: en iyi hâlin, kesintisiz bir seri yapsa nereye kadar gider?": "Вопрос простой: как далеко зайдёт твоя лучшая версия без перерывов?",
