  "🔀 Kesintisiz bir dahi: kimse onu durduramadı.": "🔀 Гений без перерывов: его никто не смог остановить.",
  "Hiç Emekli Olmasaydı": "Если бы он не ушёл",
  "Herkes zirvede bıraktığını söyledi. Ama ya bırakmasaydın?": "Все говорили, что ты ушёл на вершине. А если бы не ушёл?",
  "Welter sıklette yeni bir kral var: Kamaru Usmanov. Güçlü, sabırlı, durdurulamaz.": "В полусреднем весе новый король — Камару Усманов. Сильный, терпеливый, неудержимый.",
