  "Öğrencilerin hırslandı. Moral +5.": "Ученики завелись. Мораль +5.",
  "Atışma büyüdü. Bazıları sevdi, bazıları hiç sevmedi.": "Перепалка разрослась. Кому-то понравилось, кому-то нет.",
  "🏆 YILIN ANTRENÖRÜ: {0}! {1}. yılın ödülü senin. Ödül {2}, ün +8.": "🏆 ТРЕНЕР ГОДА: {0}! Награда {1}-го года твоя. Приз {2}, репутация +8.",
