  "Bu sefer kafese sen girmiyorsun. Garaj salonundan başla, sokaktan yetenek bul, köşelerinde dur ve onları UCC kemerine taşı.": "На этот раз в клетку выходишь не ты. Начни с гаражного зала, найди таланты на улице, стой в их углу и доведи до пояса UCC.",
  "Yetenek avı: potansiyeli yüksek gençleri bul ve kaydet.": "Поиск талантов: находи и записывай перспективную молодёжь.",
  "Her öğrenciye antrenman odağı ver: vuruş, güreş, kondisyon…": "Задай каждому ученику фокус: ударка, борьба, выносливость…",
  "Maç günü köşedesin: oyun planını ve raunt arası talimatı sen verirsin.": "В день боя ты в углу: план на бой и подсказка между раундами — за тобой.",
  "Antrenör seviyeni yükselt: taktik, gözcülük, motivasyon, menajerlik.": "Расти как тренер: тактика, скаутинг, мотивация, менеджмент.",
  "Salon olayları, yıl sonu Yılın Antrenörü ödülü ve dünya salon sıralaması.": "События в зале, награда «Тренер года» и мировой рейтинг залов.",
  "HOCANIN ADI": "ИМЯ ТРЕНЕРА",
