  "Antrenör Modu": "Режим тренера",
  "Bu sefer hoca sensin: salonunu kur, şampiyon yetiştir": "Теперь тренер — ты: построй зал, воспитай чемпионов",
  "Üstüne yürü, ritmi sen belirle. Nefes götürür.": "Иди вперёд, задавай темп. Съедает дыхание.",
