  "Cutman'e öncelik ver: doktor maçı durdurmasın.": "Катмен в приоритете: врач не должен остановить бой.",
  "Erken baskıcı: ilk rauntta yüklenir, sonra düşer.": "Ранний прессинг: давит в первом раунде, потом сдаёт.",
  "Kontracı: üstüne gelinmesini bekler, açığı cezalandırır.": "Контрпанчер: ждёт атаки и наказывает за ошибки.",
  "Güreşçi: indirmeye ve kafes kenarında boğmaya çalışır.": "Борец: ищет проходы и душит у сетки.",
