  "{0} önde. {1} çaresizleşmeye başladı.": "{0} впереди. {1} начинает отчаиваться.",
  "Kartlarda öndeyiz. Şimdi akıllı olmak lazım.": "По запискам мы впереди. Теперь надо быть умнее.",
