  "{0} ritmi buldu; böyle giderse kaybederiz.": "{0} нашёл ритм; так мы проиграем.",
  "Başa baş gidiyor. Bu raunt maçı belirleyebilir.": "Ноздря в ноздрю. Этот раунд может всё решить.",
  "{0} ile {1} arasında kılı kırk yaran bir maç.": "Бой {0} и {1} идёт на волоске.",
  "{0} önde ama nefes nefese. Ağzı açık, elleri düşük.": "{0} впереди, но задыхается. Рот открыт, руки опущены.",
  "Puanda öndeyiz ama {0} nefesini kaybediyor.": "Мы впереди по очкам, но {0} теряет дыхание.",
  "{0} yoruldu: elleri düşüyor, ağzından nefes alıyor.": "{0} устал: руки падают, дышит ртом.",
  "{0} bacaklarını zor taşıyor. Fırsat kapıda.": "{0} еле таскает ноги. Шанс рядом.",
  "Kesik var: {0} kaşından kanıyor, doktor köşeye bakıyor.": "Рассечение: у {0} кровь над бровью, врач смотрит в угол.",
