  "{0} sarsıldı, bacakları titriyor. Köşeye zor geldi.": "{0} потрясён, ноги дрожат. Еле дошёл до угла.",
  "Son yumrukla {0} sallandı. Gözleri dalgın.": "{0} поплыл от последнего удара. Взгляд мутный.",
