  "{0} ayakta zor duruyor, gözleri kaydı.": "{0} еле стоит, глаза закатываются.",
  "{0} indirip kafese dayıyor; {1} altta eziliyor.": "{0} переводит и прижимает к сетке; {1} страдает снизу.",
  "Raundun yarısı yerde geçti, {0} üstte kontrol etti.": "Половина раунда в партере, {0} контролировал сверху.",
