  "Gövdeye gelen her vuruşta {0} eğiliyor, dirsekleri iniyor.": "От каждого удара по корпусу {0} сгибается, локти опускаются.",
  "{0} karaciğerini korumak için elleri indiriyor.": "{0} опускает руки, защищая печень.",
