  "Bu kategoride dövüşçün yok. Önce bir kariyer başlat.": "У тебя нет бойца в этой категории. Сначала начни карьеру.",
  "Arkadaşının dövüşçüsü yapay zekâyla karşına çıkar. Sen de kodunu paylaş, seninkiyle dövüşsünler.": "Боец друга выходит против тебя под управлением ИИ. Поделись своим кодом, чтобы друзья сразились с твоим.",
