  "Henüz hayaletin yok. Arkadaşlarından kod iste ya da kendi kodunu paylaş.": "Призраков пока нет. Попроси код у друзей или поделись своим.",
  "Karnen: {0}-{1}-{2}": "Твой счёт: {0}-{1}-{2}",
