  "🔮 TAHMİN KARTI": "🔮 КАРТА ПРОГНОЗОВ",
  "Kartın zirvesindeki maçları tahmin et. Doğru kazanan para kazandırır; favori olmayanı bilmek daha değerli. Bitiriş ya da kararı da bilirsen ek ödül.": "Спрогнозируй главные бои вечера. Верный победитель приносит деньги, а угаданный андердог ценится выше. Угадаешь досрочную победу или решение — получишь бонус.",
