  "Rauntun bitmesine {0}:{1}": "До конца раунда {0}:{1}",
  "Seyirci ayakta, “durdur” diye bağıranlar var.": "Зал на ногах, кто-то кричит «останови!».",
  "Eli rakibinin sırtına iki kez hafifçe dokundu.": "Его рука дважды легко хлопнула соперника по спине.",
  "Kolları gevşedi, artık savaşmıyor.": "Руки обмякли, он больше не борется.",
  "Yüzü kızarmış, elleri yavaşlıyor.": "Лицо покраснело, руки двигаются всё медленнее.",
  "Kol açısı tehlikeli, yüzünü buruşturuyor.": "Рука под опасным углом, он морщится.",
  "Ellerini kenetledi, kilidi açmaya çalışıyor.": "Сцепил руки, пытается разорвать захват.",
