  "Kan doğrudan gözüne akıyor, sürekli siliyor.": "Кровь заливает глаз, он постоянно вытирает.",
  "Kaşta küçük bir kesik, kan yanağa sızıyor.": "Небольшое рассечение, кровь стекает по щеке.",
