  "🏅 {0} FİNALİ": "🏅 ФИНАЛ: {0}",
  "Kazanırsan madalya senin ve bir üst basamağa çıkarsın. Kaybedersen 2 puan gider, yeniden denersin.": "Победишь — медаль твоя, и ты поднимаешься выше. Проиграешь — минус 2 очка и новая попытка.",
  "{0} {1} şampiyonu oldun! +${2}, +{3} gelişim puanı, popülerlik +{4}.": "{0} Ты победил: {1}! +${2}, +{3} очков развития, популярность +{4}.",
  "⏩ Herkes konuşuyor: Bölge Şampiyonası'nı atladın, doğrudan {0}!": "⏩ О тебе говорят все: ты пропускаешь Региональный чемпионат и идёшь сразу сюда: {0}.",
  "⬆️ Sıradaki basamak: {0}.": "⬆️ Следующий уровень: {0}.",
  "Finali kaybettin. Yeniden denemek için {0}/{1} puan.": "Финал проигран. Очки до новой попытки: {0}/{1}.",
  "🏅 {0}: {1}/{2} puan": "🏅 {0}: {1}/{2} очков",
  "🔥 Finale çıkma hakkı kazandın! Sıradaki teklifte final var.": "🔥 Ты заслужил финал! Он будет в следующем списке соперников.",
  "🥇 Ulusal şampiyonsun! Profesyonel organizasyonlar kapında sıraya girdi.": "🥇 Ты чемпион страны! Профессиональные лиги выстроились в очередь.",
  "Amatörde yeterince tecrübe kazandın. İki bölgesel organizasyon seni profesyonel kadrosuna istiyor!": "Ты набрался любительского опыта. Две региональные лиги хотят видеть тебя в профессиональном составе!",
  "AMATÖR LİGİ · {0}. BASAMAK": "ЛЮБИТЕЛЬСКАЯ ЛИГА · УРОВЕНЬ {0}",
  "Ulusal şampiyonsun. Sıradaki durak profesyonel kafes.": "Ты чемпион страны. Следующая остановка — профессиональная клетка.",
  "Final hazır! Sıradaki rakip listesinde.": "Финал готов! Он будет в следующем списке соперников.",
  "Finale {0} puan kaldı · Galibiyet 2-5 puan, yenilgi -1": "До финала очков: {0} · Победа 2-5 очков, поражение -1",
  "Şehir Ligi → Bölge Şampiyonası → Ulusal Turnuva. Yükseliş Grand Prix'i ilk madalyadan sonra kestirme yol olabilir.": "Городская лига → Региональный чемпионат → Национальный турнир. Гран-при восхождения может стать коротким путём после первой медали.",
  "🥋 Hangi Kulüp?": "🥋 Какой клуб?",
  "Şehir Ligi'nde adın duyuldu. Üç kulüp seni antrenmana çağırıyor. Yerin belli olsun, sonrası kolay.": "О тебе заговорили в Городской лиге. Три клуба зовут тренироваться. Выбери свой дом, дальше будет легче.",
  "Mahalle salonu: herkes tanır": "Зал в районе: тебя знают все",
