  "Mahalle arkana geçti. Popülerlik +3.": "Район за тебя. Популярность +3.",
  "Her gün minderdesin. Güreş +2.": "Каждый день на ковре. Борьба +2.",
  "Eller hızlandı. Vuruş +2.": "Руки стали быстрее. Ударка +2.",
  "🧰 Yarı Zamanlı İş": "🧰 Подработка",
  "Amatörde para yok, fatura var. Bir tanıdık bu ay gece vardiyası öneriyor.": "Любителям не платят, а счета приходят. Знакомый предлагает ночные смены на этот месяц.",
