  "Vardiyalar zor ama kasa doldu. +$700, sağlık -6.": "Смены были тяжёлыми, зато есть деньги. +$700, здоровье -6.",
  "Salondan çıkmadın. +1 gelişim puanı.": "Ты не выходил из зала. +1 очко развития.",
  "🎽 Milli Takım Daveti": "🎽 Вызов в сборную",
  "Federasyon seni milli takım kampına çağırdı. Sert bir hafta, ama herkesin gözü üstünde olacak.": "Федерация вызвала тебя на сбор сборной. Тяжёлая неделя, но все будут смотреть на тебя.",
  "Kampa git: popülerlik ve tecrübe": "Поехать на сбор: популярность и опыт",
  "Lige odaklan: dinlen": "Сосредоточиться на лиге: отдых",
  "Forma sırtında! Popülerlik +4, IQ +2, sağlık -8.": "Ты надел форму сборной! Популярность +4, IQ +2, здоровье -8.",
  "Daveti kibarca geri çevirdin. Sağlık +8.": "Ты вежливо отказался от вызова. Здоровье +8.",
