  "🏛️ TARİH YAZILDI! {0}: artık tüm zamanların 1 numarası sensin, {1} geride kaldı. +${2}, popülerlik +{3}.": "🏛️ ИСТОРИЯ! {0}: теперь ты номер 1 всех времён, позади остался {1}. +${2}, популярность +{3}.",
  "🏛️ Rekor: {0} listesinde {1} dövüşçüsünü geçtin, sıran #{2}. +${3}, popülerlik +{4}.": "🏛️ Рекорд: в списке «{0}» ты обошёл: {1}. Твоё место #{2}. +${3}, популярность +{4}.",
  "UCC Tarihi": "История UCC",
  "{0} tarihin 1 numarası: {1}. Bu rekor uzun süre konuşulacak.": "{0}, номер 1 в истории: {1}. Об этом рекорде будут говорить долго.",
