  "🗞️ {0}: \"Sert vurduğunu biliyorum. Çenemi çalıştırdım.\"": "🗞️ {0}: «Знаю, что бьёшь сильно. Я укрепил челюсть».",
  "🗞️ {0} kampında tek konu: nakavtçıya karşı nasıl ayakta kalınır?": "🗞️ В лагере {0} одна тема: как устоять против нокаутёра.",
  "🗞️ {0} bütün kampı güreş savunmasıyla geçirdi: \"Beni yere indiremeyecek.\"": "🗞️ {0} весь лагерь работал над защитой от проходов: «Меня не свалишь».",
  "🗞️ {0}: \"Herkes yerde boğuluyor, ben boğulmayacağım.\"": "🗞️ {0}: «Все задыхаются в партере. Но не я».",
