  "{0} kroşeyi patlattı, {1} yere yığıldı! Nakavt!": "{0} пробил хук, {1} рухнул! Нокаут!",
  "{0} üstten yumruk yağdırıyor, hakem durdurdu! TKO!": "{0} осыпает ударами сверху, рефери остановил! ТКО!",
  "Gong çaldı. Karar jüri kartlarında.": "Гонг. Всё решат записки судей.",
  "Kartlar okundu: {0}. Kazanan {1}!": "Записки оглашены: {0}. Победитель — {1}!",
  "Bu gece senin kariyerini bitireceğim.": "Сегодня я закончу твою карьеру.",
  "Herkes beni konuşacak, sen de dahil.": "Все будут говорить обо мне, и ты тоже.",
  "O kemer zaten benim, sadece takacağım.": "Этот пояс уже мой, осталось его надеть.",
  "Sen sadece bir basamaksın.": "Ты всего лишь ступенька.",
  "Ekibim arkamda. Hazırım.": "Команда за мной. Я готов.",
  "Saygım var ama o kafeste kardeş yok.": "Уважаю, но в клетке братьев нет.",
  "Köşemi dinleyeceğim, gerisi gelir.": "Буду слушать свой угол, остальное приложится.",
  "Erken bitireceğim, akşam yemeğine yetişmem lazım.": "Закончу быстро, мне надо успеть на ужин.",
  "Antrenman mı? Yeteneğim yeter.": "Тренировки? Мне хватит таланта.",
  "Uzatmayalım şu işi.": "Не будем затягивать.",
  "Kameralar hazır mı? Bu an viral olacak.": "Камеры готовы? Этот момент станет вирусным.",
  "Seni yarın herkes benim videomdan tanıyacak.": "Завтра все узнают тебя по моему видео.",
  "Gülümse, bu fotoğraf manşette.": "Улыбнись, это фото на первую полосу.",
  "Bu maç benim maaşımı ikiye katlayacak.": "Этот бой удвоит мою зарплату.",
  "Sponsorlarım bakıyor, iyi görünmem lazım.": "Спонсоры смотрят, мне надо хорошо выглядеть.",
  "Ödemeyi aldım, şimdi şovu izle.": "Деньги получены, теперь смотри шоу.",
  "Yanlış kapıyı çaldın.": "Ты постучал не в ту дверь.",
  "Gözlerinde korku görüyorum.": "Вижу страх в твоих глазах.",
  "Üçüncü raunda kalmazsın.": "До третьего раунда ты не доживёшь.",
  "Menajerin seni kurbanlığa getirmiş.": "Твой менеджер привёл тебя на убой.",
  "Bu gece ışıkları söndüreceğim.": "Сегодня я выключу свет.",
  "Tek seferlik alım: sınırsız ajans kariyeri, UCC sözleşmeleri, şampiyonlar ve Yılın Menajeri ödülü.": "Разовая покупка: неограниченные карьеры агентства, контракты UCC, чемпионы и награда «Менеджер года».",
  "Menajer Modu · {0}": "Режим менеджера · {0}",
