  "MENAJER MODU": "РЕЖИМ МЕНЕДЖЕРА",
  "Bu sefer kafese sen çıkmıyorsun. Dövüşçülerin kariyeri, parası ve sağlığı senin telefonunda.": "На этот раз в клетку выходишь не ты. Карьера, деньги и здоровье твоих бойцов — в твоём телефоне.",
  "Telefonun hiç susmaz: dövüşçüler, patronlar, gazeteciler ve rakip menajerler. Her cevabın bir sonucu var.": "Телефон не умолкает: бойцы, боссы, журналисты и менеджеры-конкуренты. У каждого ответа есть последствия.",
  "Organizasyonların gizli bütçesine karşı pazarlık yap; rövanş, çıkış ve sakatlık maddeleri yıllar sonra işine yarar.": "Торгуйся против скрытых бюджетов организаций; пункты о реванше, выходе и травмах окупаются годы спустя.",
  "Yetenek avına çık, gençleri komisyon pazarlığıyla imzala, rakip ajanslardan önce davran.": "Ищи таланты, подписывай молодых, торгуясь о комиссии, и опережай конкурентов.",
  "İki dövüşçün aynı kemere yürürse? Organizasyon onları birbirine eşlemek isteyecek.": "А если двое твоих бойцов идут к одному поясу? Организация захочет свести их друг с другом.",
  "Doktor uyarır, para çağırır. Dövüşçünün sağlığı mı, maaş günü mü?": "Врач предупреждает, деньги зовут. Здоровье бойца или день зарплаты?",
  "Bodrum kat ofisinden gökdelene: şampiyonlar çıkar, Yılın Menajeri ol.": "Из подвала в небоскрёб: расти чемпионов, стань менеджером года.",
