  "Dövüşçülerin kariyeri telefonunda: pazarlık yap, şampiyon çıkar": "Карьера твоих бойцов в телефоне: торгуйся и расти чемпионов",
  "Hakem, Antrenör ve Menajer Modu, bütün efsaneler, reklamsız oyun ve 6 kozmetik paket.": "Режимы рефери, тренера и менеджера, все легенды, игра без рекламы и 6 косметических наборов.",
  "Hakem, Antrenör ve Menajer Modu ile Tam Paket'i tamamla": "Дополни Полный набор режимами рефери, тренера и менеджера",
  "Reklamsız oyun, ödüller anında, 5 kariyer yuvası, bütün efsaneler ve Altın Seri. Hakem, Antrenör ve Menajer Modu dahil değil.": "Игра без рекламы, награды сразу, 5 слотов карьеры, все легенды и Золотая серия. Режимы рефери, тренера и менеджера не входят.",
  "+{0} ile Tam Paket: Hakem, Antrenör, Menajer Modu ve 6 kozmetik paket de gelsin": "Полный набор за +{0}: режимы рефери, тренера и менеджера и 6 косметических наборов в придачу",
  "Tam Paket'e yükselt: Hakem, Antrenör, Menajer Modu ve 6 kozmetik paket": "Перейти на Полный набор: режимы рефери, тренера и менеджера и 6 косметических наборов",
  "Menajer Modu: kendi ajansın, kendi şampiyonların": "Режим менеджера: своё агентство, свои чемпионы",
  "Kabus": "Кошмар",
  "Oyunu kolay bulanlar için. Rakipler çok güçlü ve taktiğini çabuk okur, ücretler %40 az, gelişim yavaş, sakatlıklar kalıcı iz bırakabilir. Efsane puanın 1,5 kat sayılır.": "Для тех, кому игра кажется лёгкой. Соперники очень сильны и быстро читают твою тактику, гонорары на 40% ниже, прогресс медленный, травмы могут оставить след навсегда. Очки наследия считаются ×1,5.",
  "Kabustan Uyanan": "Проснувшийся от кошмара",
  "Kabus zorluğunda herhangi bir kemer kazan.": "Выиграй любой пояс на сложности «Кошмар».",
  "Kabusun Efendisi": "Повелитель кошмара",
  "Kabus zorluğunda UCC kemerini kazan.": "Выиграй пояс UCC на сложности «Кошмар».",
  "💀 Kabus: {0} kalıcı iz bıraktı. {1} -1.": "💀 Кошмар: {0} оставила след навсегда. {1} -1.",
  "Nakavt olmak çenende derin iz bıraktı. Çene -{0}.": "Нокаут оставил глубокий след на твоём подбородке. Подбородок -{0}.",
  "Kabus zorluğunda bir kemer kazan": "Выиграй пояс на сложности «Кошмар»",
  "Kabus zorluğunda UCC kemerini kazan": "Выиграй пояс UCC на сложности «Кошмар»",
  "Kabus Kafesi": "Клетка кошмара",
  "Kabus Kartı": "Карточка кошмара",
  "Kabus Dumanı": "Дым кошмара",
  "YOL Evreni": "Вселенная YOL",
  "Kariyer yuvası {0}": "Слот карьеры {0}",
  "YOL EVRENİ": "ВСЕЛЕННАЯ YOL",
  "Bütün modların aynı dünyada geçiyor. Kariyerindeki dövüşçülerin Menajer Modu'nda rakip olarak teklif edilir; Menajer Modu'ndaki dövüşçülerin de büyük ligde ve UCC'de kariyerinin karşısına çıkar.": "Все твои режимы живут в одном мире. Бойцы из карьеры появляются соперниками в режиме менеджера, а бойцы твоего агентства выходят против тебя в карьере в высших лигах и в UCC.",
  "ÇAPRAZ MAÇ": "ПЕРЕКРЁСТНЫЕ",
  "ÇAPRAZ MAÇLAR": "ПЕРЕКРЁСТНЫЕ БОИ",
  "Henüz modlar arası maç yok. Büyük lige çıktıkça ve Menajer Modu'nda teklifler geldikçe dövüşçülerin karşılaşacak.": "Перекрёстных боёв пока нет. Когда выйдешь в высшие лиги и в режиме менеджера пойдут предложения, твои бойцы встретятся.",
  "Bağlantı için iki tarafta da dövüşçü gerekir: aktif bir kariyer ve Menajer Modu'nda aynı sıklette bir dövüşçü.": "Нужны бойцы с обеих сторон: активная карьера и боец той же весовой категории в режиме менеджера.",
  "KARİYER DÖVÜŞÇÜLERİN": "ТВОИ БОЙЦЫ ИЗ КАРЬЕРЫ",
  "Henüz kariyerin yok.": "Карьер пока нет.",
  "MENAJER MODU DÖVÜŞÇÜLERİN": "ТВОИ БОЙЦЫ В РЕЖИМЕ МЕНЕДЖЕРА",
  "Menajer Modu'nda ajans kurup dövüşçü imzaladığında burada görünürler.": "Когда откроешь агентство и подпишешь бойцов в режиме менеджера, они появятся здесь.",
  "Bütün modların aynı dünyada: dövüşçülerin birbirinin karşısına çıkar": "Все режимы в одном мире: твои бойцы встречаются друг с другом",
  "🌐 YOL Evreni: kariyer modundaki dövüşçün!": "🌐 Вселенная YOL: твой боец из карьеры!",
  "🌐 YOL Evreni: Menajer Modu'ndaki dövüşçün!": "🌐 Вселенная YOL: твой боец из режима менеджера!",
  "Menajer: {0}, kariyer modundaki dövüşçün {1} ile karşılaştı ve {2}.": "Менеджер: {0} встретился с твоим бойцом из карьеры {1} и {2}.",
  "Kariyer: {0}, Menajer Modu'ndaki dövüşçün {1} ile karşılaştı ve {2}.": "Карьера: {0} встретился с твоим бойцом из режима менеджера {1} и {2}.",
