  "Organizasyonların ve UCC yıldızlarının adını istediğin gibi değiştir. Düzenlemelerini kodla paylaş ya da arkadaşının kodunu yükle.": "Переименуй организации и звёзд UCC как хочешь. Делись правками через код или загрузи код друга.",
  "{0} düzenleme": "Правок: {0}",
  "Organizasyon adları kaydedildi.": "Названия организаций сохранены.",
  "Kadro kaydedildi.": "Состав сохранён.",
  "Editör kodu yüklendi.": "Код редактора загружен.",
