  "Kariyer editörü Şampiyon Paketi'nde": "Редактор карьеры — в наборе «Чемпион»",
  "Kendi dövüşçünün adını ve lakabını, rakiplerinin isimlerini ve istatistikleri değiştirmek Şampiyon Paketi ya da Tam Paket sahiplerine açık. Organizasyon ve UCC kadrosu editörü herkese ücretsiz.": "Менять имя и прозвище своего бойца, имена соперников и характеристики могут владельцы наборов «Чемпион» или «Полный». Редактор организаций и состава UCC бесплатен для всех.",
  "Paketlere bak": "Посмотреть наборы",
  "Düzenlenecek kariyer yok. Önce bir kariyer başlat.": "Нет карьеры для редактирования. Сначала начни карьеру.",
  "Kariyer kaydedildi. İstatistikler değiştiği için bu kariyer artık başarım kazanmaz.": "Карьера сохранена. Характеристики изменены, поэтому эта карьера больше не получает достижения.",
  "Kariyer kaydedildi.": "Карьера сохранена.",
