  "Değiştirirsen bu kariyer artık başarım kazanmaz ve oynayarak açılan ödüllerde sayılmaz.": "Если изменишь, эта карьера больше не получает достижения и не учитывается в наградах, открываемых игрой.",
  "RAKİPLER": "СОПЕРНИКИ",
