  "EDİTÖR KODUN": "ТВОЙ КОД РЕДАКТОРА",
  "{0} düzenleme bu kodda. Paylaş; arkadaşların tek dokunuşla yüklesin.": "В этом коде правок: {0}. Поделись, чтобы друзья загрузили их одним касанием.",
  "Henüz düzenleme yok. Organizasyon ya da kadro düzenleyince kodun burada oluşur.": "Правок пока нет. Код появится здесь, когда отредактируешь организацию или состав.",
  "Kodu paylaş": "Поделиться кодом",
  "YOL için editör kodum ({0} düzenleme). Oyunda Editör > Paylaş'a yapıştır: {1}": "Мой код редактора YOL (правок: {0}). В игре вставь его в Редактор > Поделиться: {1}",
