  "Organizasyonları ve UCC kadrosunu istediğin gibi adlandır, kodla paylaş": "Переименуй организации и состав UCC и делись кодом",
  "Patron Modu": "Режим промоутера",
  "Kendi organizasyonunu kur: kartı sen kur, kemerleri sen ver, UCC'yi geç": "Создай свою организацию: сам составляй карды, вручай пояса и обгони UCC",
  "Patron Modu: kendi organizasyonun, kendi kemerlerin": "Режим промоутера: своя организация, свои пояса",
  "Patron, Menajer, Antrenör ve Hakem Modu, bütün efsaneler, reklamsız oyun ve 6 kozmetik paket.": "Режимы промоутера, менеджера, тренера и рефери, все легенды, игра без рекламы и 6 косметических наборов.",
  "Reklamsız oyun, ödüller anında, 5 kariyer yuvası, bütün efsaneler ve Altın Seri. Patron, Menajer, Antrenör ve Hakem Modu dahil değil.": "Игра без рекламы, мгновенные награды, 5 слотов карьеры, все легенды и Золотая серия. Режимы промоутера, менеджера, тренера и рефери не входят.",
  "+{0} ile Tam Paket: Patron, Menajer, Antrenör, Hakem Modu ve 6 kozmetik paket de gelsin": "+{0} за Полный набор: ещё режимы промоутера, менеджера, тренера, рефери и 6 косметических наборов",
  "Tam Paket'e yükselt: Patron, Menajer, Antrenör, Hakem Modu ve 6 kozmetik paket": "Перейти на Полный набор: режимы промоутера, менеджера, тренера, рефери и 6 косметических наборов",
  "Patron, Menajer, Antrenör ve Hakem Modu ile Tam Paket'i tamamla": "Дополни Полный набор режимами промоутера, менеджера, тренера и рефери",
  "{0} KAZANDI!": "{0} ПОБЕЖДАЕТ!",
  "Ana maç ister, kamerayı sever. Tanıtımda altın değerinde.": "Хочет главный бой, любит камеру. Золото для промо.",
  "Kavgacı": "Задира",
  "Laf atar, ateşi yükseltir. Basın toplantısında olay çıkarabilir.": "Провоцирует и разжигает. Может устроить скандал на пресс-конференции.",
  "Sessiz": "Молчун",
  "Az konuşur, çok çalışır. Bilet sattırmaz ama sorun da çıkarmaz.": "Мало говорит, много работает. Билеты не продаёт, но и проблем не создаёт.",
  "Her imzada zam ister, rakip teklife en açık olan odur.": "Просит прибавку при каждой подписи и охотнее всех слушает чужие предложения.",
  "Organizasyonuna bağlıdır, rakip teklifleri çoğunlukla geri çevirir.": "Предан организации, обычно отказывает конкурентам.",
  "Kemer maçı istiyor": "Хочет титульный бой",
  "Daha çok para istiyor": "Хочет больше денег",
