  "Ana maç istiyor": "Хочет главный бой",
  "Depo salonu": "Склад",
  "Taraftar dövüşçüleri yakından görür. Ucuz, takipçi getirir.": "Фанаты видят бойцов вблизи. Дёшево, приносит подписчиков.",
